INSERT INTO `surat_pernyataan_templates` VALUES (1,'Surat Pernyataan Belum Pernah Menikah','Pernyataan masih berstatus perjaka/perawan/janda/duda & belum terikat perkawinan. Disertai 2 saksi.','belum-pernah-menikah.docx',0,'2026-06-25 23:52:44','2026-06-25 23:52:44'),(2,'Surat Pernyataan Persetujuan Menikah','Pernyataan belum menikah beserta data calon pasangan dan persetujuan ayah & ibu kandung.','persetujuan-menikah.docx',1,'2026-06-25 23:52:44','2026-06-25 23:52:44'),(3,'Surat Pernyataan Duda','Pernyataan status duda (tidak lagi bersama istri) sejak tanggal tertentu.','ditinggalkan-istri.docx',2,'2026-06-25 23:52:44','2026-06-25 23:52:44'),(4,'Surat Pernyataan Janda','Pernyataan status janda (tidak lagi bersama suami) sejak tanggal tertentu.','ditinggalkan-suami.docx',3,'2026-06-25 23:52:44','2026-06-25 23:52:44'),(5,'Surat Pernyataan Perbedaan Data','Pernyataan perbedaan nama/tanggal lahir di beberapa dokumen yang merujuk pada orang yang sama.','perbedaan-data.docx',4,'2026-06-25 23:52:44','2026-06-25 23:52:44'),(6,'Surat Pernyataan Penghasilan','Pernyataan pekerjaan dan besaran penghasilan per bulan.','penghasilan.docx',5,'2026-06-25 23:52:44','2026-06-25 23:52:44'),(7,'Surat Pernyataan Domisili','Pernyataan domisili tempat tinggal di wilayah Kel. Sepinggan Baru beserta status rumah (sendiri/kontrak/sewa).','domisili-sementara.docx',6,'2026-06-25 23:52:44','2026-06-25 23:52:44');
